/**
 * Pure tests for the triage-context secret scan port.
 *
 * The oracle fixture is generated by
 * `apps/crq-python/triage_context_scan_vectors.py` from the PRODUCTION Python
 * `crq_repair.triage_context_scan`. The `flatten` cases replay every context
 * through an injected recording scanner and compare the exact synthetic patch,
 * the verdict, and the exception class (and `ContextScanError.reason`) Python
 * raises. The `real` cases run the same patches through the production TS
 * scanner (`makeRepairScan`) and compare Python's `secret_scan_diff` verdict.
 *
 * No process, filesystem write, clock, provider or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import { makeRepairScan } from '../../../src/adapters/crq/repairScan.js';
import type { GitleaksEffects } from '../../../src/ops/dev/denylist.js';
import { parseJsonValue, type JsonValue } from '../../../src/policy/crq/jsonValue.js';
import {
  ContextScanError,
  TriageContextScanRefusal,
  TriageScanPolicyFailure,
  errorReason,
  triageContextScan,
  triageContextScanPatch,
  type TriageContextScanner,
} from '../../../src/policy/crq/triageContextScan.js';

type ScannerSpec = 'clean' | 'dirty' | { raises: string; message: string };

interface FlattenCase {
  name: string;
  context_json: string;
  scanner: ScannerSpec;
  result: {
    scanner_calls: number;
    patch: string | null;
    verdict?: boolean;
    raises?: string;
    reason?: string;
    message?: string;
  };
}

interface RealCase {
  name: string;
  context_json: string;
  result: { clean: boolean; denylist_hits: number; gitleaks: string };
}

const fixture = JSON.parse(
  readFileSync(
    new URL(
      '../../../apps/crq-python/fixtures/crq-triage-context-scan/cases.json',
      import.meta.url,
    ),
    'utf8',
  ),
) as {
  rules: { id: string; regex: string; path?: string }[];
  flatten: FlattenCase[];
  real: RealCase[];
};

/** Parse the ordered context text with the production JSON reader. */
function json(text: string): JsonValue {
  return parseJsonValue(text);
}

/** Python class names the port maps to a typed refusal (uncaught in Python). */
const REFUSED = new Set(['KeyError', 'TypeError', 'AttributeError']);

/** The recording scanner Python's oracle uses, as a TS seam. */
function recordingScanner(spec: ScannerSpec, calls: string[]): TriageContextScanner {
  return (patch) => {
    calls.push(patch);
    if (spec === 'clean' || spec === 'dirty') return spec === 'clean';
    if (spec.raises === 'OSError' || spec.raises === 'RuntimeError') {
      throw new TriageScanPolicyFailure(spec.raises, spec.message);
    }
    // Every other class is outside the OSError/RuntimeError family: Python
    // never catches it, so the port's seam throws something unrelated.
    throw new RangeError(spec.raises);
  };
}

describe('triageContextScan oracle (flatten, verdict, typed refusal)', () => {
  for (const item of fixture.flatten) {
    test(item.name, async () => {
      const calls: string[] = [];
      const scanner = recordingScanner(item.scanner, calls);
      const outcome = await triageContextScan(json(item.context_json), scanner).then(
        (verdict) => ({ verdict }) as { verdict: boolean; error?: undefined },
        (error: unknown) => ({ error }) as { verdict?: undefined; error: unknown },
      );
      const expected = item.result;
      expect(calls.length).toBe(expected.scanner_calls);
      expect(calls[0] ?? null).toBe(expected.patch);
      if (expected.raises === undefined) {
        expect(outcome.error).toBeUndefined();
        expect(outcome.verdict).toBe(expected.verdict);
      } else if (expected.raises === 'ContextScanError') {
        expect(outcome.error).toBeInstanceOf(ContextScanError);
        expect((outcome.error as ContextScanError).reason).toBe(expected.reason);
        expect((outcome.error as ContextScanError).message).toBe(expected.message);
      } else if (expected.scanner_calls === 0 && REFUSED.has(expected.raises)) {
        // Python raised before the scanner was asked (a damaged context).
        expect(outcome.error).toBeInstanceOf(TriageContextScanRefusal);
      } else {
        // A non-OSError/RuntimeError scanner failure propagates unchanged, never wrapped.
        expect(outcome.error).toBeInstanceOf(RangeError);
        expect(outcome.error).not.toBeInstanceOf(ContextScanError);
        expect((outcome.error as RangeError).message).toBe(expected.raises);
      }
    });
  }

  test('the patch builder alone matches every recorded patch', () => {
    for (const item of fixture.flatten) {
      if (item.result.patch === null) {
        expect(() => triageContextScanPatch(json(item.context_json)), item.name).toThrow(
          TriageContextScanRefusal,
        );
      } else {
        expect(triageContextScanPatch(json(item.context_json)), item.name).toBe(item.result.patch);
      }
    }
  });

  test('the oracle exercises every branch', () => {
    const raised = new Set(fixture.flatten.map((item) => item.result.raises));
    for (const name of [
      'ContextScanError',
      'KeyError',
      'TypeError',
      'AttributeError',
      'ValueError',
    ]) {
      expect(raised.has(name), name).toBe(true);
    }
    expect(fixture.flatten.some((item) => item.result.verdict === true)).toBe(true);
    expect(fixture.flatten.some((item) => item.result.verdict === false)).toBe(true);
  });
});

describe('errorReason', () => {
  test('is the port of triage.error_reason', () => {
    expect(errorReason('  a \n b c  ', 'OSError')).toBe('a b c');
    expect(errorReason('   ', 'RuntimeError')).toBe('RuntimeError');
    expect(errorReason('', 'OSError')).toBe('OSError');
    expect(errorReason('abcdef', 'OSError', 3)).toBe('abc');
    expect([...errorReason('\u{1f600}'.repeat(5), 'OSError', 4)]).toHaveLength(4);
  });
});

/** Gitleaks is unavailable in the oracle, so no effect may ever run. */
const unavailableGitleaks: GitleaksEffects = {
  makeScratchDir: () => Promise.reject(new Error('gitleaks must not run')),
  removeScratchDir: () => Promise.resolve(),
  runCommand: () => Promise.reject(new Error('gitleaks must not run')),
};

describe('triageContextScan against the production TS scanner', () => {
  for (const item of fixture.real) {
    test(item.name, async () => {
      const scan = makeRepairScan({
        rules: fixture.rules.map((rule) => ({ ...rule, description: 'oracle rule' })),
        gitleaksEffects: unavailableGitleaks,
        gitleaksAvailable: () => false,
      });
      const clean = await triageContextScan(json(item.context_json), async (patch) => {
        const result = await scan.scanDiff({
          patch,
          name: 'triage-context',
          base: null,
          head: '',
        });
        expect(result.report.denylistHits).toBe(item.result.denylist_hits);
        expect(result.report.gitleaks).toBe(item.result.gitleaks);
        return result.clean;
      });
      expect(clean).toBe(item.result.clean);
    });
  }
});
